{{-- row-tone: baris terlambat = warna lembut + garis tegas di bawah; selesai = huruf abu-abu. --}}
<x-dl::grid id="grid-status" row-tone="tone" :rows="array_map(fn ($r) => $r + ['tone' => ['TERLAMBAT' => 'danger', 'SELESAI' => 'muted'][$r['status']] ?? null], \App\Support\DemoData::workOrders())" actions="worklist" :active-key="null" :new-record="false" search="Cari WO / produk..."
    :stats="[['label' => 'Total WO'], ['label' => 'Jalan', 'where' => ['status' => 'JALAN'], 'tone' => 'accent'], ['label' => 'Terlambat', 'where' => ['status' => 'TERLAMBAT'], 'tone' => 'danger'], ['label' => 'Selesai', 'where' => ['status' => 'SELESAI'], 'tone' => 'success']]"
    :columns="[['key' => 'wo', 'label' => 'No. WO'], ['key' => 'product', 'label' => 'Produk'], ['key' => 'qty', 'label' => 'Qty', 'type' => 'number'], ['key' => 'stage', 'label' => 'Tahapan', 'type' => 'steps', 'steps' => ['Plat', 'Cetak', 'Laminasi', 'Pond', 'Lem', 'QC', 'Kirim']], ['key' => 'progress', 'label' => 'Progres', 'type' => 'progress'], ['key' => 'due', 'label' => 'Due Date', 'type' => 'date'], ['key' => 'status', 'label' => 'Status', 'type' => 'badge', 'tones' => ['JALAN' => 'info', 'TERLAMBAT' => 'danger', 'SELESAI' => 'success']]]" />
